const fs=require('fs'),vm=require('vm'),assert=require('node:assert/strict'),acorn=require('../motion-engines-runtime/node_modules/acorn'),mock=require('../../tests/helpers/ae-3d-mock.cjs'),bridge=require('../../editor_plugins/caption-3d/bridge.cjs');
const checks=[],findings=[];function probe(name,fn){try{fn();checks.push({name,passed:true});}catch(e){checks.push({name,passed:false});findings.push({trigger:name,expected:'Safe outline creation retaining owner data',actual:e.message,impact:'Isolated contract failed; native impact unverified',fixed_after_final_review:false});}}function call(h,p){return JSON.parse(h.run(bridge.nativeRequest(process.cwd(),p)));}function request(h){return {action:'insert',family:'3d1',variant:'boost',sound_fx:false,context:call(h,{action:'context'}),request_id:'a'.repeat(32)};}function placed(){const h=mock();assert(call(h,request(h)).ok);h.outer=h.owner._layers.find(l=>l.kind==='av');h.owner.selectedLayers=[h.outer];return h;}function update(h){return {action:'depth',depth:140,context:call(h,{action:'selected'}).context,request_id:'b'.repeat(32)};}function ring(c){return c._layers.filter(l=>/^Storylens 3D1 outline /.test(l.comment||''));}
probe('failure halfway through a new outline removes staging and retains owner composition/layers',()=>{const h=mock(),before=h.items.length,add=h.context.app.project.items.addComp;h.context.app.project.items.addComp=(...a)=>{const c=add(...a),text=c.layers.addText;let calls=0;c.layers.addText=t=>{if(++calls===6)throw Error('Injected outline allocation failure');return text(t);};return c;};assert(call(h,request(h)).error);assert.equal(h.items.length,before);assert.equal(h.owner.renderer,'OWNER RENDERER');assert.deepEqual(h.owner._layers,[h.camera]);});
probe('failed placed-title outline upgrade retains original source, locked ring and transforms',()=>{const h=placed(),old=h.outer.source,before=h.items.length,p=update(h),duplicate=old.duplicate.bind(old);old.duplicate=()=>{const c=duplicate();c.layers.addText=()=>{throw Error('Injected outline allocation failure');};return c;};assert(call(h,p).error);assert.equal(h.outer.source,old);assert.equal(h.items.length,before);assert.equal(ring(old).length,16);assert(ring(old).every(l=>l.locked));});
probe('upgrading one shared instance leaves the other instance and its outline unchanged',()=>{const h=placed(),old=h.outer.source,other=h.owner.layers.add(old);assert(call(h,update(h)).ok);assert.equal(other.source,old);assert.notEqual(h.outer.source,old);assert.equal(ring(old).length,16);assert.equal(ring(h.outer.source).length,16);assert(ring(h.outer.source).every(l=>h.outer.source._layers.includes(l.parent)));});
probe('uncertain successful upgrade retry does not stack another ring or extra sources',()=>{const h=placed(),p=update(h);assert(call(h,p).ok);const before=h.items.length;assert(call(h,p).reused);assert.equal(h.items.length,before);assert.equal(ring(h.outer.source).length,16);});
probe('another project cannot receive the outline update',()=>{const h=placed(),p=update(h),old=h.outer.source,before=h.items.length;p.context.project_id='another';assert(call(h,p).error);assert.equal(h.outer.source,old);assert.equal(h.items.length,before);});
probe('ring follows the local text anchor evenly and hides with the parent face',()=>{const h=placed(),o=ring(h.outer.source).filter(l=>l.parent.name==='EDIT - MAIN'),anchor=[37,19,0],positions=o.map(l=>vm.runInNewContext(l.property('ADBE Transform Group').property('ADBE Position').expression,{parent:{anchorPoint:anchor},thisComp:{layer:()=>({effect:()=>()=>4})}}));assert.equal(positions.length,8);for(const p of positions){assert(Math.abs(Math.hypot(p[0]-37,p[1]-19)-4)<1e-6);assert(p[2]>0&&p[2]<1);}assert(Math.abs(positions.reduce((s,p)=>s+p[0]-37,0))<1e-6);const opacity=o[0].property('ADBE Transform Group').property('ADBE Opacity').expression;assert.equal(vm.runInNewContext(opacity,{parent:{active:false,opacity:100}}),0);assert.equal(vm.runInNewContext(opacity,{parent:{active:true,opacity:42}}),42);});
probe('quote-like edited words remain caption data, not executable expression source',()=>{const h=placed(),p=h.outer.source.layer('EDIT - MAIN').property('ADBE Text Properties').property('ADBE Text Document'),text='OWNER "; app.project.save(); //';p.setValue({...p.value,text});assert(call(h,update(h)).ok);for(const l of ring(h.outer.source)){const property=l.property('ADBE Text Properties').property('ADBE Text Document');assert(!property.expression.includes(text));}assert.equal(h.saves,0);});
probe('shipped engines and every generated outline expression retain compatible syntax',()=>{const h=placed();acorn.parse(bridge.nativeRequest(process.cwd(),update(h)),{ecmaVersion:3});for(const name of ['hinglish_app/static/caption-3d-camera-engine.jsx','output/ae-3d1/Create 3D1 Titles.jsx'])acorn.parse(fs.readFileSync(name,'utf8'),{ecmaVersion:3});for(const l of ring(h.outer.source)){for(const n of ['ADBE Anchor Point','ADBE Position','ADBE Opacity'])acorn.parse(l.property('ADBE Transform Group').property(n).expression,{ecmaVersion:3});acorn.parse(l.property('ADBE Text Properties').property('ADBE Text Document').expression,{ecmaVersion:3});}});
const result={stage:'final_adversarial_review',computer_control:false,native_application_validation:false,checks,findings};fs.writeFileSync('output/ae-3d-caption-library/black-outline/final-review.json',JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify(result,null,2));if(findings.length)process.exitCode=1;
